import{initializeTheme,mountThemePicker}from'./theme.js';
const root=document.documentElement,body=document.body,slug=body.dataset.designStudy;
const names={delta:'Delta / Field Notes',roveia:'Roveia / Connected',atmos:'Atmos / Signal Atlas'};
initializeTheme();document.querySelectorAll('[data-study-theme]').forEach(mountThemePicker);
const reduced=matchMedia('(prefers-reduced-motion:reduce)');let enabled=true;
try{enabled=localStorage.getItem('portfolio-motion')!=='off'}catch{}
const motionAllowed=()=>enabled&&!reduced.matches;
const entries=[...document.querySelectorAll('[data-study][id]')];
const toolbar=document.createElement('aside');toolbar.className='study-review';toolbar.setAttribute('aria-label','Design review controls');
toolbar.innerHTML=`<span class="study-review-title">${names[slug]||'Design lab'}</span><button type="button" data-review-map>Section map</button><button type="button" data-review-labels>Labels: sections</button><button type="button" data-review-motion aria-pressed="true">Motion on</button><a href="design-studies.html">All studies ↗</a><nav class="review-sites" aria-label="Switch design study">${Object.entries(names).map(([id,name])=>`<a href="study-${id}.html"${id===slug?' aria-current="page"':''}>${name.split(' / ')[0]}</a>`).join('')}</nav>`;
body.append(toolbar);body.dataset.labels='sections';
const toast=document.createElement('div');toast.className='study-copy-toast';toast.hidden=true;toast.setAttribute('role','status');body.append(toast);let toastTimer;
async function copyID(id){clearTimeout(toastTimer);toast.replaceChildren();(map.open?map:body).append(toast);toast.hidden=false;try{await navigator.clipboard.writeText('#'+id);toast.textContent='Copied #'+id}catch{toast.textContent='Select and copy this ID:';const input=document.createElement('input');input.value='#'+id;input.readOnly=true;toast.append(input);input.focus();input.select()}toastTimer=setTimeout(()=>toast.hidden=true,5000)}
for(const entry of entries){entry.classList.add('study-anchor');if(entry.matches('section,footer,header')||entry.dataset.kind==='section')entry.dataset.kind='section';const badge=document.createElement('button');badge.type='button';badge.className='study-id-label';badge.textContent='#'+entry.id;badge.setAttribute('aria-label','Copy section ID '+entry.id);badge.title=entry.dataset.design||entry.dataset.study;badge.addEventListener('click',event=>{event.preventDefault();event.stopPropagation();copyID(entry.id)});entry.append(badge)}
const map=document.createElement('dialog');map.className='study-map';map.setAttribute('aria-labelledby','study-map-title');map.innerHTML='<header><div><p class="study-kicker">EXACT DETAILS / YOUR PICK LIST</p><h2 id="study-map-title">Find a detail.<br>Keep its ID.</h2></div><button type="button" aria-label="Close section map">×</button></header><p class="study-map-intro">Every entry is a real element on this page. Jump to it, copy its selector, and tell me what to keep or change. Labels can be hidden for a clean preview.</p><label class="sr-only" for="study-map-search">Search sections and design details</label><input id="study-map-search" placeholder="Try navigation, cards, animation, footer…" type="search"><p class="study-map-count" role="status"></p><div class="study-map-list"></div>';
body.append(map);const list=map.querySelector('.study-map-list'),count=map.querySelector('.study-map-count');
function renderMap(){const q=map.querySelector('input').value.toLowerCase(),filtered=entries.filter(e=>(e.id+' '+e.dataset.study+' '+e.dataset.design).toLowerCase().includes(q));count.textContent=filtered.length+' of '+entries.length+' labeled details';list.replaceChildren();for(const entry of filtered){const row=document.createElement('article');row.className='study-map-item';const a=document.createElement('a');a.href='#'+entry.id;a.textContent=entry.dataset.study;const id=document.createElement('span');id.textContent='#'+entry.id;a.append(id);a.addEventListener('click',()=>{map.close();highlight(entry)});const copy=document.createElement('button');copy.type='button';copy.textContent='Copy ID';copy.setAttribute('aria-label','Copy '+entry.id);copy.addEventListener('click',()=>copyID(entry.id));const p=document.createElement('p');p.textContent=entry.dataset.design||'';row.append(a,copy,p);list.append(row)}}
function highlight(entry){entry.classList.add('study-target');setTimeout(()=>entry.classList.remove('study-target'),3000)}
map.querySelector('header button').addEventListener('click',()=>map.close());map.addEventListener('click',e=>{if(e.target===map){const r=map.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)map.close()}});map.querySelector('input').addEventListener('input',renderMap);toolbar.querySelector('[data-review-map]').addEventListener('click',()=>{renderMap();map.showModal()});
const labelModes=['sections','all','off'];toolbar.querySelector('[data-review-labels]').addEventListener('click',event=>{body.dataset.labels=labelModes[(labelModes.indexOf(body.dataset.labels)+1)%3];event.currentTarget.textContent='Labels: '+body.dataset.labels});
function syncMotion(){const on=motionAllowed();root.dataset.motion=on?'on':'off';body.classList.toggle('study-motion-on',on);const button=toolbar.querySelector('[data-review-motion]');button.textContent=on?'Motion on':'Motion quiet';button.setAttribute('aria-pressed',String(on));window.dispatchEvent(new CustomEvent('portfolio:motionchange',{detail:{enabled:on}}));schedule()}
toolbar.querySelector('[data-review-motion]').addEventListener('click',()=>{if(reduced.matches){toast.textContent='Motion follows your device’s reduced-motion setting.';toast.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.hidden=true,5000);return}enabled=!enabled;try{localStorage.setItem('portfolio-motion',enabled?'on':'off')}catch{}syncMotion()});reduced.addEventListener('change',syncMotion);
for(const trigger of document.querySelectorAll('[data-study-menu]')){const menu=document.getElementById(trigger.getAttribute('aria-controls'));if(!menu)continue;function close(){menu.dataset.open='false';trigger.setAttribute('aria-expanded','false')}trigger.addEventListener('click',()=>{const open=menu.dataset.open!=='true';menu.dataset.open=String(open);trigger.setAttribute('aria-expanded',String(open))});menu.addEventListener('click',e=>{if(e.target.closest('a'))close()});document.addEventListener('keydown',e=>{if(e.key==='Escape')close()});document.addEventListener('pointerdown',e=>{if(!menu.contains(e.target)&&!trigger.contains(e.target))close()})}
const reveals=[...document.querySelectorAll('[data-reveal]')],scenes=[...document.querySelectorAll('[data-scroll-scene]')],parallax=[...document.querySelectorAll('[data-parallax]')];
const observer=new IntersectionObserver(items=>{for(const item of items)if(item.isIntersecting){item.target.classList.add('is-revealed');observer.unobserve(item.target)}},{threshold:.08});reveals.forEach(e=>observer.observe(e));
let scheduled=0;function paintScroll(){scheduled=0;const h=innerHeight;for(const element of scenes){const r=element.getBoundingClientRect(),progress=Math.max(0,Math.min(1,-r.top/Math.max(1,r.height-h)));element.style.setProperty('--section-progress',motionAllowed()?progress:'.5')}for(const element of parallax){const r=element.getBoundingClientRect(),amount=motionAllowed()?((h*.5-r.top-r.height*.5)*Number(element.dataset.parallax||.1)):0;element.style.setProperty('--parallax-y',Math.max(-80,Math.min(80,amount)).toFixed(2)+'px')}}function schedule(){if(!scheduled&&!document.hidden)scheduled=requestAnimationFrame(paintScroll)}
window.addEventListener('scroll',schedule,{passive:true});window.addEventListener('resize',schedule,{passive:true});document.addEventListener('visibilitychange',()=>{if(document.hidden&&scheduled){cancelAnimationFrame(scheduled);scheduled=0}else schedule()});
const art=document.querySelector('.homelab-art'),world=document.querySelector('#room-world'),hero=document.querySelector('.homelab'),popout=document.querySelector('#room-popout');let lastWidth=0;
function alignRoom(){if(!art||!world)return;if(art.dataset.detail!=='true'){const r=art.getBoundingClientRect(),width=Math.ceil(Math.max(r.width,r.height*1672/941));if(width!==lastWidth){lastWidth=width;art.style.setProperty('--study-room-width',width+'px')}}if(popout){const r=world.getBoundingClientRect(),h=hero.getBoundingClientRect();popout.style.left=(r.left-h.left)+'px';popout.style.top=(r.top-h.top)+'px';popout.style.width=r.width+'px';popout.style.height=(r.height*1.19)+'px'}}
const geometry=new ResizeObserver(alignRoom);if(art)geometry.observe(art);if(world)geometry.observe(world);alignRoom();
const phone=matchMedia('(max-width:760px)');function hint(){const e=document.querySelector('.room-hint');if(e)e.lastChild.textContent=phone.matches?' Swipe to explore. Touch a machine.':' Touch a machine. Every light has a story.'}phone.addEventListener('change',hint);hint();
syncMotion();schedule();window.addEventListener('hashchange',()=>{const e=document.getElementById(decodeURIComponent(location.hash.slice(1)));if(e)highlight(e)});window.addEventListener('pagehide',()=>{observer.disconnect();geometry.disconnect();if(scheduled)cancelAnimationFrame(scheduled);clearTimeout(toastTimer)},{once:true});
